// Inside one double-roller gin, cut open and much larger than life. A rough leather roller turns; a steel knife (the fixed
// knife) presses along it. The fibres catch on the roller and are drawn under the knife, but the seeds are too big to pass:
// a moving knife (the beater) knocks up and down and pushes the stripped seeds off; they fall through a grid below. The
// fibre (lint) comes out the other side, clean of seeds. Gentle on the fibre: long staple cotton is ginned this way.
const roll = W.group();
roll.add(W.mesh(W.cyl(60, 60, 400, 32), W.plastic('#4a3426', { rough: 0.85 }), { rot: [0, 0, 90] }));
for (let i = 0; i < 16; i++) { const a = i / 16 * Math.PI * 2; roll.add(W.mesh(W.box(400, 2, 6), W.plastic('#3a281c'), { at: [0, Math.cos(a) * 60, Math.sin(a) * 60], rot: [a * 57.3, 0, 0] })); }
W.add(roll, { label: 'తోలు రోలర్' });
const fk = W.group();
fk.add(W.mesh(W.box(420, 8, 90), W.metal('#c3c8cc', { rough: 0.3 }), { at: [0, 64, 40], rot: [-20, 0, 0] }));
W.add(fk, { label: 'స్థిర కత్తి' });
const mk = W.group();
mk.add(W.mesh(W.box(420, 14, 40), W.metal('#8d959c', { rough: 0.4 }), { at: [0, 0, 0] }));
for (const x of [-180, 180]) mk.add(W.mesh(W.box(12, 120, 12), W.metal('#6f767e'), { at: [x, -60, -10] }));
const beater = W.group({ at: [0, 95, -70] }); beater.add(mk);
W.add(beater, { label: 'కదిలే కత్తి' });
const grid = W.group();
for (let i = 0; i < 10; i++) grid.add(W.mesh(W.box(6, 6, 160), W.metal('#9aa3ab'), { at: [-180 + i * 40, -40, -140] }));
W.add(grid, { label: 'గింజల జాలీ' });
const NS = 18, seeds = new THREE.InstancedMesh(new THREE.SphereGeometry(1, 10, 8), W.plastic('#5a4a3a'), NS);
const NF = 90, fib = new THREE.InstancedMesh(new THREE.IcosahedronGeometry(1, 1), W.fabric('#f6f4ee'), NF);
const sg = W.group(); sg.add(seeds); W.add(sg, { label: 'పత్తి గింజలు' });
const fg = W.group(); fg.add(fib); W.add(fg, { label: 'దూది' });
const M = new THREE.Matrix4(), Q = new THREE.Quaternion(), P = new THREE.Vector3(), Z = new THREE.Vector3();
const su = Array.from({ length: NS }, (_, i) => i / NS), fu = Array.from({ length: NF }, (_, i) => i / NF);
W.onTick((t, dt) => {
  const k = Math.max(0.2, W.env.spool);
  roll.rotation.x -= dt * 1.6 * k;
  beater.position.y = 95 + Math.sin(t * 6 * k) * 22;
  for (let i = 0; i < NS; i++) {
    su[i] = (su[i] + dt * 0.1 * k) % 1;
    const u = su[i], x = -180 + ((i * 0.618) % 1) * 360;
    if (u < 0.5) P.set(x, 150 - u * 120, -120 + u * 140); else P.set(x, 90 - (u - 0.5) * 400, -60 - (u - 0.5) * 180);
    seeds.setMatrixAt(i, M.compose(P, Q, Z.set(9, 6, 6)));
  }
  seeds.instanceMatrix.needsUpdate = true;
  for (let i = 0; i < NF; i++) {
    fu[i] = (fu[i] + dt * 0.12 * k) % 1;
    const u = fu[i], x = -190 + ((i * 0.618) % 1) * 380;
    if (u < 0.35) P.set(x, 150 - u * 160, -110 + u * 200);
    else { const a = Math.PI * 0.6 - (u - 0.35) * 3.4; P.set(x, Math.sin(a) * 64, Math.cos(a) * 64); }
    const s = u < 0.35 ? 9 : 6 + 3 * Math.sin(i);
    fib.setMatrixAt(i, M.compose(P, Q, Z.set(s * 1.4, s * 0.7, s)));
  }
  fib.instanceMatrix.needsUpdate = true;
});
